targetScope = 'local'

extension Cloudflare

@description('Cloudflare Zone ID for the domain.')
@minLength(32)
@maxLength(32)
param zoneId string

@description('Security rule expression to evaluate.')
param securityRuleExpression string
// Example: '(ip.src.country eq "CN")'

@description('Whether the security rule is enabled.')
param enabled bool = true

// Block traffic from country using Cloudflare free plan security rules
resource blockCountryTraffic 'SecurityRule' = {
  name: 'blockCountryTraffic'
  zoneId: zoneId
  description: 'Block requests originating from specified country'
  expression: securityRuleExpression
  action: 'block'
  enabled: enabled
}

// Outputs
output securityRuleName string = blockCountryTraffic.name
output securityRuleAction string = blockCountryTraffic.action
output securityRuleExpression string = blockCountryTraffic.expression
output securityRuleEnabled bool = blockCountryTraffic.enabled
output securityRuleId string = blockCountryTraffic.ruleId

targetScope = 'local'

extension Cloudflare

@description('Cloudflare Zone ID for the domain.')
@minLength(32)
@maxLength(32)
param zoneId string

@description('URL pattern to match using * wildcards (e.g. example.com/old-page*).')
param urlPattern string

@description('The target URL to redirect matching requests to.')
param redirectUrl string

@description('HTTP status code for the redirect.')
@allowed([301, 302])
param statusCode int = 301

@description('Whether the redirect rule is enabled.')
param enabled bool = true

resource oldPageRedirect 'RedirectRule' = {
  name: 'oldPageRedirect'
  zoneId: zoneId
  urlPattern: urlPattern
  redirectUrl: redirectUrl
  statusCode: statusCode
  enabled: enabled
}

output redirectRuleName string = oldPageRedirect.name
output redirectRuleId string = oldPageRedirect.pageRuleId
output redirectRuleUrlPattern string = oldPageRedirect.urlPattern
output redirectRuleUrl string = oldPageRedirect.redirectUrl
output redirectRuleStatusCode int = oldPageRedirect.statusCode
output redirectRuleEnabled bool = oldPageRedirect.enabled
